import React from 'react';
import sha256 from 'sha256';
import { login, logout } from '../services/user-service';

class LoginPage extends React.Component {
  constructor(props) {
    super(props);

    logout();

    this.state = {
      username: '',
      password: '',
      submitted: false,
      loading: false,
      error: ''
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(e) {
    const { name, value } = e.target;
    this.setState({ [name]: value });
  }


  handleSubmit(e) {
    e.preventDefault();

    this.setState({ submitted: true });
    const { username, password, returnUrl } = this.state;

    // stop here if form is invalid
    if (!(username && password)) {
      return;
    }

    this.setState({ loading: true });
    login(username, password)
      .then(
        user => {
          const { from } = this.props.location.state || { from: { pathname: "/" } };
          this.props.history.push(from);
        },
        error => this.setState({ error, loading: false })
      );
  }

  render() {
    const { username, password, submitted, loading, error } = this.state;
    return (
      <div className="col-md-6 col-md-offset-3">
        <div>
          <h3>Congratulations!  You have your UI up and running!</h3>
          <span>&nbsp;</span>
          <span>&nbsp;</span>
        </div>
        <h4>If you have your Node API running, you can attempt to login below.</h4>
        <span>&nbsp;</span>
        <form name="form" onSubmit={this.handleSubmit} >
          <div className={'form-group' + (submitted && !username ? ' has-error' : '')}>
            <label htmlFor="username">Username</label>
            <input type="text" className="form-control" name="username" value={username} onChange={this.handleChange} />
            {submitted && !username &&
              <div className="help-block">Username is required</div>
            }
          </div>
          <div class="alert alert-danger">
            <strong>WARNING:</strong> Please do not use your LAN password.  The password will be provided to you by your coaches.
          </div>
          <div className={'form-group' + (submitted && !password ? ' has-error' : '')}>
            <label htmlFor="password">Password</label>
            <input type="password" className="form-control" name="password" value={password} onChange={this.handleChange} />
            {submitted && !password &&
              <div className="help-block">Password is required</div>
            }
          </div>
          <div className="form-group">
            <button className="btn btn-primary" disabled={loading}>Submit</button>
            {loading &&
              <img src="data:image/gif;base64," />
            }
          </div>
          {error &&
            <div className={'alert alert-danger'}>{error}</div>
          }
        </form>
      </div>
    );
  }
}

export default LoginPage;



